function escapeByte(byte) {
  if (byte === 0x09) {
    return '\\t';
  }

  if (byte === 0x0a) {
    return '\\n';
  }

  if (byte === 0x0d) {
    return '\\r';
  }

  if (byte === 0x27) {
    return "\\'";
  }

  if (byte === 0x5c) {
    return '\\\\';
  }

  if (byte >= 0x20 && byte <= 0x7e) {
    return String.fromCharCode(byte);
  }

  return `\\x${byte.toString(16).padStart(2, '0')}`;
}

export function toPythonBytesLiteral(buffer) {
  let rendered = "b'";

  for (const byte of buffer.values()) {
    rendered += escapeByte(byte);
  }

  rendered += "'";
  return rendered;
}

